// "Why it matters" numbers, the prompt box, and the "Beyond the leaderboard" charts.
// Data: window.SITE_INSIGHTS, generated by analysis/site_insights.py from the released predictions.
(function () {
  'use strict';
  var I = window.SITE_INSIGHTS; if (!I) return;
  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); };
  var M = I.models, by = {}; M.forEach(function (m) { by[m.name] = m; });
  var inst = M.filter(function (m) { return m.group === 'instruction'; });
  var f1 = function (v) { return (Math.round(v * 10) / 10).toFixed(1); };
  var f0 = function (v) { return String(Math.round(v)); };
  var minmax = function (a, k) { var v = a.map(function (m) { return m[k]; }); return [Math.min.apply(null, v), Math.max.apply(null, v)]; };

  // ---------- why it matters
  var H = I.commit_hist, N = I.n_insuf_queries, cum = 0, median = 0;
  for (var k = 0; k < H.length; k++) { cum += H[k]; if (cum >= N / 2) { median = k; break; } }
  var gr = minmax(inst, 'guess_true');
  $('why-stats').innerHTML = [
    [median + ' of ' + I.n_inst, 'open instruction models name an order on a typical input whose frames do not establish one (median over ' + N.toLocaleString('en-US') + ' queries)'],
    [f0(100 * H[I.n_inst] / N) + '%', 'of those queries get an order from all ' + I.n_inst + ' of them; only ' + f1(100 * H[0] / N) + '% get UNCLEAR from every one'],
    [f0(gr[0]) + '&ndash;' + f0(gr[1]) + '%', 'of the orders they name match the order that actually happened, where chance gives 50%: informed guesses, not observations']
  ].map(function (s) { return '<div class="bigstat"><b>' + s[0] + '</b><span>' + s[1] + '</span></div>'; }).join('');
  $('why-rho').innerHTML = 'across the 16 open configurations the two accuracies have a rank correlation of only &rho;&nbsp;=&nbsp;' + I.spearman_open.toFixed(2);
  $('prompt-text').textContent = I.prompt;

  // ---------- evidence type per observation set + action classes (replaces the static figure)
  (function () {
    var el = $('set-chart'); if (!el || !I.set_counts) return;
    var KEYS = [['ord', 'Orderable'], ['U0', 'U0'], ['U1', 'U1'], ['U2', 'U2']], nf = 0;
    for (var k in I.set_counts.H) nf += I.set_counts.H[k];
    var W = 400, L = 26, R = 6, bw = W - L - R, rowH = 30, top = 44, h1 = top + 5 * rowH + 48;
    var x = function (v, tot) { return v / tot * bw; };
    var o = '<svg viewBox="0 0 ' + W + ' ' + (h1 + 196) + '">';
    o += '<text x="0" y="14" class="sc-h">(a) Evidence type of each observation set</text>';
    var lx = 0;
    KEYS.forEach(function (kk) { o += '<rect x="' + lx + '" y="24" width="10" height="10" rx="2" class="sc-' + kk[0] + '"/><text x="' + (lx + 14) + '" y="33" class="sc-l">' + kk[1] + '</text>'; lx += kk[0] === 'ord' ? 84 : 42; });
    o += '<text x="' + W + '" y="33" class="sc-l" text-anchor="end">' + nf + ' families</text>';
    'HLKP'.split('').forEach(function (s, i) {
      var c = I.set_counts[s], y = top + i * rowH, cx = L;
      o += '<text x="0" y="' + (y + 16) + '" class="sc-set">' + s + '</text>';
      KEYS.forEach(function (kk) {
        var v = c[kk[0]], w = x(v, nf); if (!v) return;
        o += '<g><title>' + s + ' · ' + kk[1] + ': ' + v + ' families</title><rect x="' + cx + '" y="' + (y + 2) + '" width="' + w + '" height="' + (rowH - 8) + '" class="sc-' + kk[0] + '"/>' +
             (w > 26 ? '<text x="' + (cx + w / 2) + '" y="' + (y + 17) + '" text-anchor="middle" class="sc-v ' + (kk[0] === 'U0' ? 'dk' : '') + '">' + v + '</text>' : '') + '</g>';
        cx += w;
      });
    });
    // all inputs: shares of the 4 x families inputs, then the split of the insufficient ones
    var tot4 = {}, nIn = 4 * nf, yA = top + 4 * rowH + 6, cxA = L, pc = function (v, d) { return (100 * v / d).toFixed(1) + '%'; };
    KEYS.forEach(function (kk) { tot4[kk[0]] = 0; 'HLKP'.split('').forEach(function (s) { tot4[kk[0]] += I.set_counts[s][kk[0]]; }); });
    o += '<line x1="0" x2="' + W + '" y1="' + (yA - 3) + '" y2="' + (yA - 3) + '" class="sc-rule"/>';
    o += '<text x="0" y="' + (yA + 16) + '" class="sc-set">All</text>';
    KEYS.forEach(function (kk) {
      var v = tot4[kk[0]], w = x(v, nIn); if (!v) return;
      o += '<g><title>All inputs · ' + kk[1] + ': ' + v.toLocaleString('en-US') + ' of ' + nIn.toLocaleString('en-US') + '</title><rect x="' + cxA + '" y="' + (yA + 2) + '" width="' + w + '" height="' + (rowH - 8) + '" class="sc-' + kk[0] + '"/>' +
           (w > 34 ? '<text x="' + (cxA + w / 2) + '" y="' + (yA + 17) + '" text-anchor="middle" class="sc-v ' + (kk[0] === 'U0' ? 'dk' : '') + '">' + pc(v, nIn) + '</text>' : '') + '</g>';
      cxA += w;
    });
    var nIns = tot4.U0 + tot4.U1 + tot4.U2;
    o += '<text x="0" y="' + (yA + rowH + 14) + '" class="sc-l">' + nIn.toLocaleString('en-US') + ' inputs: ' + tot4.ord.toLocaleString('en-US') + ' orderable (' + pc(tot4.ord, nIn) + '), ' + nIns.toLocaleString('en-US') + ' insufficient (' + pc(nIns, nIn) + ')</text>';
    o += '<text x="0" y="' + (yA + rowH + 31) + '" class="sc-l">Insufficient: U0 ' + tot4.U0 + ' (' + pc(tot4.U0, nIns) + ') · U1 ' + tot4.U1 + ' (' + pc(tot4.U1, nIns) + ') · U2 ' + tot4.U2 + ' (' + pc(tot4.U2, nIns) + ')</text>';
    var CL = I.class_counts, tot = 0, max = 0; for (var c2 in CL) { tot += CL[c2]; max = Math.max(max, CL[c2]); }
    var y2 = h1 + 28;
    o += '<text x="0" y="' + y2 + '" class="sc-h">(b) Action class of each target (' + tot.toLocaleString('en-US') + ' targets)</text>';
    Object.keys(CL).forEach(function (c3, i) {
      var y = y2 + 14 + i * 34, w = CL[c3] / max * (bw - 150);
      o += '<text x="0" y="' + (y + 15) + '" class="sc-l">' + c3 + '</text><rect x="140" y="' + y + '" width="' + w + '" height="20" rx="3" class="sc-cls"/>' +
           '<text x="' + (146 + w) + '" y="' + (y + 15) + '" class="sc-l">' + CL[c3] + '</text>';
    });
    el.innerHTML = o + '</svg>';
  })();

  // ---------- SVG helpers
  var NS = 'http://www.w3.org/2000/svg';
  function svg(w, h, label) { return '<svg viewBox="0 0 ' + w + ' ' + h + '" role="img" aria-label="' + esc(label) + '">'; }
  function tip(m, lines) { return '<title>' + esc(m.name + '\n' + lines.join('\n')) + '</title>'; }
  function txt(x, y, s, cls, anchor) { return '<text x="' + x + '" y="' + y + '" class="' + (cls || '') + '"' + (anchor ? ' text-anchor="' + anchor + '"' : '') + '>' + s + '</text>'; }

  // 1) rank by ordering vs rank by withholding
  function slope() {
    var W = 640, top = 34, step = 24.5, h = top + M.length * step + 8;
    var ro = M.slice().sort(function (a, b) { return b.ord - a.ord; }), ri = M.slice().sort(function (a, b) { return b.insuf - a.insuf; });
    var y = function (i) { return top + i * step + step / 2; };
    var X1 = 214, X2 = 426, out = svg(W, h, 'Rank by ordering accuracy against rank by withholding accuracy');
    out += txt(X1, 16, 'Ranked by ordering accuracy', 'ax-h', 'end') + txt(X2, 16, 'Ranked by withholding accuracy', 'ax-h', 'start');
    M.forEach(function (m) {
      var a = ro.indexOf(m), b = ri.indexOf(m), big = Math.abs(a - b) >= 6;
      out += '<g class="row g-' + m.group + (big ? ' big' : '') + '">' + tip(m, ['ordering ' + f1(m.ord) + '% (rank ' + (a + 1) + ')', 'withholding ' + f1(m.insuf) + '% (rank ' + (b + 1) + ')']) +
        '<line x1="' + (X1 + 10) + '" y1="' + y(a) + '" x2="' + (X2 - 10) + '" y2="' + y(b) + '" class="ln"/>' +
        '<circle cx="' + (X1 + 10) + '" cy="' + y(a) + '" r="4" class="pt"/><circle cx="' + (X2 - 10) + '" cy="' + y(b) + '" r="4" class="pt"/>' +
        txt(X1, y(a) + 4, esc(m.name) + ' <tspan class="v">' + f1(m.ord) + '</tspan>', 'lab', 'end') +
        txt(X2, y(b) + 4, '<tspan class="v">' + f1(m.insuf) + '</tspan> ' + esc(m.name), 'lab', 'start') + '</g>';
    });
    return out + '</svg>';
  }

  // 2) UNCLEAR on orderable vs insufficient inputs
  function scatter() {
    var W = 640, Hh = 470, L = 58, R = 24, T = 18, B = 52, xmax = 35;
    var x = function (v) { return L + v / xmax * (W - L - R); }, y = function (v) { return T + (1 - v / 100) * (Hh - T - B); };
    var out = svg(W, Hh, 'UNCLEAR rate on orderable inputs against UNCLEAR rate on insufficient inputs');
    out += '<defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" class="arrowhead"/></marker></defs>';
    out += '<rect x="' + x(0) + '" y="' + y(100) + '" width="' + (x(6) - x(0)) + '" height="' + (y(80) - y(100)) + '" class="ideal"/>' + txt(x(13.5), y(96), '← selective: withholds only when it should', 'note');
    [0, 25, 50, 75, 100].forEach(function (v) { out += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + y(v) + '" y2="' + y(v) + '" class="grid"/>' + txt(L - 8, y(v) + 4, v + '%', 'tick', 'end'); });
    [0, 10, 20, 30].forEach(function (v) { out += txt(x(v), Hh - B + 20, v + '%', 'tick', 'middle'); });
    out += txt((L + W - R) / 2, Hh - 8, 'UNCLEAR on inputs whose frames DO establish the order  (lower is better) →', 'ax-h', 'middle');
    out += '<text transform="translate(16,' + ((T + Hh - B) / 2) + ') rotate(-90)" class="ax-h" text-anchor="middle">UNCLEAR on insufficient inputs  (higher is better) →</text>';
    I.pairs.forEach(function (p) {
      var a = by[p[0]], b = by[p[1]];
      out += '<line x1="' + x(a.unc_ord) + '" y1="' + y(a.insuf) + '" x2="' + x(b.unc_ord) + '" y2="' + y(b.insuf) + '" class="pair" marker-end="url(#arr)"/>';
    });
    var labelled = { 'Gemma 4 12B': [8, 4], 'Keye-VL-1.5-8B': [8, 4], 'Qwen3.8-27B': [8, 4], 'Qwen3.8-27B (Thinking)': [8, -6], 'MiMo-VL-7B-RL': [8, 4],
      'MiMo-VL-7B-RL (Thinking)': [10, 5], 'LLaVA-OneVision-2-8B': [8, -4], 'Qwen3-VL-32B-Thinking': [8, 20], 'Qwen3-VL-8B-Thinking': [8, 4], 'InternVL3.5-14B': [10, 14] };
    M.forEach(function (m) {
      out += '<g class="g-' + m.group + '">' + tip(m, ['UNCLEAR on orderable inputs ' + f1(m.unc_ord) + '%', 'UNCLEAR on insufficient inputs ' + f1(m.insuf) + '%']) +
        '<circle cx="' + x(m.unc_ord) + '" cy="' + y(m.insuf) + '" r="6.5" class="pt"/></g>';
      var l = labelled[m.name]; if (l) out += txt(x(m.unc_ord) + l[0], y(m.insuf) + l[1], esc(m.name), 'lab', l[2]);
    });
    out += txt(x(3.4) + 10, y(96) + 22, 'closed references', 'lab');
    return out + '</svg>';
  }

  // 3) and 4) horizontal bars
  function bars(key, opts) {
    var rows = M.slice().sort(function (a, b) { return b[key] - a[key]; });
    var W = 640, top = 28, step = 23.5, L = 210, R = 70, h = top + rows.length * step + 34;
    var x = function (v) { return L + v / 100 * (W - L - R); };
    var out = svg(W, h, opts.label);
    [0, 25, 50, 75, 100].forEach(function (v) { out += '<line x1="' + x(v) + '" x2="' + x(v) + '" y1="' + top + '" y2="' + (h - 28) + '" class="grid"/>' + txt(x(v), h - 10, v + '%', 'tick', 'middle'); });
    if (opts.ref != null) out += '<line x1="' + x(opts.ref) + '" x2="' + x(opts.ref) + '" y1="' + (top - 4) + '" y2="' + (h - 28) + '" class="ref"/>';
    rows.forEach(function (m, i) {
      var y = top + i * step;
      out += '<g class="row g-' + m.group + '">' + tip(m, opts.tip(m)) +
        txt(L - 10, y + step / 2 + 4, esc(m.name), 'lab', 'end') +
        '<rect x="' + x(0) + '" y="' + (y + 4) + '" width="' + Math.max(1.5, x(m[key]) - x(0)) + '" height="' + (step - 8) + '" rx="3" class="bar"/>' +
        txt(x(m[key]) + 6, y + step / 2 + 4, f1(m[key]) + (opts.suffix ? opts.suffix(m) : ''), 'v', 'start') + '</g>';
    });
    if (opts.refLabel) out += txt(x(opts.ref), top - 10, opts.refLabel, 'note', 'middle');
    return out + '</svg>';
  }

  // ---------- tabs
  var pd = I.pairs.map(function (p) { return [by[p[1]].insuf - by[p[0]].insuf, by[p[1]].unc_ord - by[p[0]].unc_ord]; });
  var avg = function (a, i) { return a.reduce(function (s, v) { return s + v[i]; }, 0) / a.length; };
  var mini = by['MiniCPM-V4.7'], rankOrd = M.slice().sort(function (a, b) { return b.ord - a.ord; }).indexOf(mini) + 1,
      rankIns = M.slice().sort(function (a, b) { return b.insuf - a.insuf; }).indexOf(mini) + 1;
  var sl = M.slice().sort(function (a, b) { return b.same_letter - a.same_letter; }), slInstr = minmax(inst, 'same_letter');
  var closedSame = minmax(M.filter(function (m) { return m.group === 'closed'; }), 'same_letter')[1];
  var thinkGuess = minmax(M.filter(function (m) { return m.group === 'thinking'; }), 'guess_true');
  var TABS = [
    { id: 'rank', label: 'Ordering ≠ withholding', big: '&rho; = ' + I.spearman_open.toFixed(2),
      title: 'A forced-choice score would rank them differently',
      body: 'MiniCPM-V4.7 is #' + rankOrd + ' of 19 at ordering (' + f1(mini.ord) + '%) and #' + rankIns + ' at withholding (' + f1(mini.insuf) + '%). Across the 16 open configurations, the rank correlation between the two is ' + I.spearman_open.toFixed(2) + ': knowing how well a model orders tells you little about whether it knows when it cannot. Lines that cross far are highlighted.',
      how: 'Ordering: accuracy on the ' + I.n_ord_queries.toLocaleString('en-US') + ' orderable queries. Withholding: accuracy (= UNCLEAR) on the ' + I.n_insuf_queries.toLocaleString('en-US') + ' insufficient queries. Spearman correlation over the 16 open configurations.',
      draw: slope },
    { id: 'sel', label: 'Selective, not cautious', big: '+' + f0(avg(pd, 0)) + ' pts',
      title: 'Thinking withholds where frames fall short',
      body: 'Switching the same model family to Thinking raises UNCLEAR on insufficient inputs by ' + f0(avg(pd, 0)) + ' points on average (arrows), while UNCLEAR on inputs that do establish the order changes by ' + (avg(pd, 1) >= 0 ? '+' : '−') + f1(Math.abs(avg(pd, 1))) + ' points. Gemma 4 12B and Keye-VL-1.5-8B show the other pattern: they withhold more, but also on a quarter or more of the inputs they could have ordered.',
      how: 'x: share of orderable queries answered UNCLEAR. y: share of insufficient queries answered UNCLEAR. Arrows connect the four instruction / Thinking pairs.',
      draw: scatter },
    { id: 'guess', label: 'Informed guesses', big: f0(gr[0]) + '&ndash;' + f0(gr[1]) + '%',
      title: 'Unsupported orders are informed guesses',
      body: 'For every insufficient query a model answered with an order, we compare that order with the one shown by the family’s K input. The open instruction models match it in ' + f0(gr[0]) + '–' + f0(gr[1]) + '% of cases, where chance gives 50%; Thinking models reach ' + f0(thinkGuess[0]) + '–' + f0(thinkGuess[1]) + '% and commit far less often, and the closed references rarely commit at all (n is shown per bar). The frames thus contain cues that favor the true order without establishing it, and a forced-choice benchmark would credit these guesses as temporal understanding.',
      how: 'Only insufficient queries answered A or B, in families whose K input is orderable. n = number of such answers.',
      draw: function () { return bars('guess_true', { label: 'Share of unsupported orders that match the true order', ref: 50, refLabel: 'chance', tip: function (m) { return ['matches the true order in ' + f1(m.guess_true) + '% of ' + m.guess_n + ' unsupported orders']; }, suffix: function (m) { return '  n=' + m.guess_n; } }); } },
    { id: 'letter', label: 'Answering the letter', big: f0(sl[0].same_letter) + '%',
      title: 'Some models answer the letter, not the video',
      body: 'Each input is asked twice with A and B exchanged. Giving the same letter both times names two opposite orders for one set of frames. ' + esc(sl[0].name) + ' does so on ' + f1(sl[0].same_letter) + '% of inputs and ' + esc(sl[1].name) + ' on ' + f1(sl[1].same_letter) + '%; the closed references on ' + f1(closedSame) + '%. This is a robustness check that a single-assignment benchmark cannot run.',
      how: 'Share of all ' + (I.n_ord_queries + I.n_insuf_queries) / 2 + ' inputs answered A/A or B/B across the original and swapped letter assignments.',
      draw: function () { return bars('same_letter', { label: 'Share of inputs with contradictory answers under swapped letters', tip: function (m) { return ['same letter under both assignments on ' + f1(m.same_letter) + '% of inputs']; } }); } }
  ];
  var cur = 0, m0 = location.hash.match(/^#analysis-(\d)$/); if (m0) cur = Math.min(TABS.length - 1, +m0[1] - 1);
  function renderTab() {
    var t = TABS[cur];
    $('an-tabs').innerHTML = TABS.map(function (x, i) { return '<button class="seg" role="tab" data-i="' + i + '" aria-selected="' + (i === cur) + '" aria-pressed="' + (i === cur) + '">' + x.label + '</button>'; }).join('');
    $('an-big').innerHTML = t.big; $('an-title').textContent = t.title; $('an-body').innerHTML = t.body; $('an-how').textContent = t.how;
    $('an-chart').innerHTML = t.draw(); $('an-chart').className = 'an-chart an-' + t.id;
  }
  $('an-tabs').addEventListener('click', function (e) { var b = e.target.closest('.seg'); if (b) { cur = +b.dataset.i; renderTab(); } });
  renderTab();
})();
